package com.tanmay.corebanking.service;
import com.tanmay.corebanking.enums.*; import com.tanmay.corebanking.exception.*; import com.tanmay.corebanking.model.*; import com.tanmay.corebanking.repository.*; import com.tanmay.corebanking.util.TransactionIdGenerator; import java.math.*; import java.util.*;
public class TransactionService {private final AccountRepository ar;private final TransactionRepository tr;public TransactionService(AccountRepository a,TransactionRepository t){ar=a;tr=t;} public BankAccount getAccount(String n){return ar.findByAccountNumber(n).orElseThrow(()->new AccountNotFoundException("Account not found: "+n));} public void deposit(String n,BigDecimal a){BankAccount x=getAccount(n);x.deposit(a);tr.save(new Transaction(TransactionIdGenerator.generate(),n,TransactionType.DEPOSIT,a,TransactionStatus.SUCCESS,"Cash deposit",null));} public void withdraw(String n,BigDecimal a){BankAccount x=getAccount(n);x.withdraw(a);tr.save(new Transaction(TransactionIdGenerator.generate(),n,TransactionType.WITHDRAWAL,a,TransactionStatus.SUCCESS,"Cash withdrawal",null));} public void transfer(String s,String r,BigDecimal a){if(s==null||r==null||s.equals(r))throw new TransferException("Sender and receiver accounts cannot be the same.");if(a==null||a.compareTo(BigDecimal.ZERO)<=0)throw new TransferException("Transfer amount must be greater than zero.");BankAccount x=getAccount(s),y=getAccount(r);BankAccount f=s.compareTo(r)<0?x:y,z=f==x?y:x;synchronized(f){synchronized(z){if(x.getBalance().compareTo(a)<0)throw new TransferException("Insufficient balance. Available balance: ₹"+x.getBalance());x.withdraw(a);y.deposit(a);tr.save(new Transaction(TransactionIdGenerator.generate(),s,TransactionType.TRANSFER_SENT,a,TransactionStatus.SUCCESS,"Money transferred to "+r,r));tr.save(new Transaction(TransactionIdGenerator.generate(),r,TransactionType.TRANSFER_RECEIVED,a,TransactionStatus.SUCCESS,"Money received from "+s,s));}}} public BigDecimal getBalance(String n){return getAccount(n).getBalance();} public List<Transaction> getTransactionHistory(String n){return tr.findByAccountNumber(n);} public List<Transaction> getMiniStatement(String n){return tr.findRecentTransactions(n,5);} }
